_RANKS = {rank: value for value, rank in enumerate("23456789TJQKA", start=2)}


def _score(hand):
    cards = hand.split()
    ranks = sorted((_RANKS[card[:-1]] for card in cards), reverse=True)
    flush = len({card[-1] for card in cards}) == 1

    counts = {}
    for rank in ranks:
        counts[rank] = counts.get(rank, 0) + 1
    by_count = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    counts_in_order = [count for _, count in by_count]

    straight = False
    if len(counts) == 5:
        if ranks[0] - ranks[4] == 4:
            straight = True
        elif ranks == [14, 5, 4, 3, 2]:
            # Ace plays low: A-2-3-4-5 is a five-high straight.
            straight = True
            ranks = [5, 4, 3, 2, 1]

    if straight and flush:
        return (8, tuple(ranks))
    if straight:
        return (4, tuple(ranks))
    if flush:
        return (5, tuple(ranks))
    if counts_in_order == [4, 1]:
        return (7, tuple(rank for rank, _ in by_count))
    if counts_in_order == [3, 2]:
        return (6, tuple(rank for rank, _ in by_count))
    if counts_in_order == [3, 1, 1]:
        return (3, tuple(rank for rank, _ in by_count))
    if counts_in_order == [2, 2, 1]:
        return (2, tuple(rank for rank, _ in by_count))
    if counts_in_order == [2, 1, 1, 1]:
        return (1, tuple(rank for rank, _ in by_count))
    return (0, tuple(ranks))


def best_hands(hands):
    scored = [(_score(hand), hand) for hand in hands]
    best = max(score for score, _ in scored)
    return [hand for score, hand in scored if score == best]

